-- Stamps (SERA) native ZPL opens with a ^FX comment before ^XA
-- ("^FX  ZPL generated by V1.0.0.0  ^FS\r\n^XA..."). V177 only recognised a
-- leading ^XA (raw) / "XlhB" (base64), so those labels were filed UNKNOWN and
-- the /labels endpoints answered empty. Re-file them as native ZPL.
--   base64("^FX") = "XkZY"
UPDATE label_package
   SET format = 'ZPL',
       source = 'CARRIER_NATIVE'
 WHERE format = 'UNKNOWN'
   AND (label_file_path LIKE '^FX%' OR label_file_path LIKE 'XkZY%');
